@media (max-height: 540px) {
  .dt-card-pool {
    --dt-card-pool-readable-height: calc(var(--runtime-viewport-height, 100dvh) - max(0.25rem, env(safe-area-inset-top)) - max(0.25rem, env(safe-area-inset-bottom)) - 3.5rem);
  }
  .dt-card-pool .dt-card-pool-panel { top: max(0.25rem, env(safe-area-inset-top)); bottom: max(0.25rem, env(safe-area-inset-bottom)); }
  .dt-card-pool .dt-card-pool-surface { display: grid; grid-template-columns: minmax(0, 1fr) 8.5rem; grid-template-rows: 1fr auto 1fr; column-gap: 0.75rem; padding-block: 0.25rem; }
  .dt-card-pool .dt-card-pool-backdrop { bottom: 0 !important; background-color: rgba(2, 6, 23, 0.92); }
  .dt-card-pool .dt-card-pool-title { grid-column: 2; grid-row: 1; align-self: end; font-size: 1rem; }
  .dt-card-pool .dt-card-pool-search { grid-column: 2; grid-row: 2; width: 100%; }
  .dt-card-pool .dt-card-pool-selection { grid-column: 1; grid-row: 1 / 4; height: 100%; max-height: none; overflow-x: auto; overflow-y: hidden; padding-bottom: 0; }
  .dt-card-pool .dt-card-pool-track { width: max-content; flex-wrap: nowrap; }
  .dt-card-pool .dt-card-pool-card { --dt-card-pool-render-width: var(--dt-card-pool-reader-width); }
  .dt-card-pool .dt-card-pool-actions { grid-column: 2; grid-row: 3; align-self: start; flex-direction: column; }
}
